Column(
    modifier = Modifier.fillMaxWidth().heightIn(max = 760.dp).padding(MonarchTheme.spacing.space4),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
) {
    MonarchStepper(steps = steps, current = step)
    when (step) {
        0 -> Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
            MonarchText(text = {{title}}, style = MonarchTextStyle.Heading, heading = true)
            MonarchText(text = {{description}}, color = MonarchTheme.colors.textMuted)
            MonarchFileUpload(
            onFiles = { accepted, _ ->
                val file = accepted.firstOrNull()
                if (file != null) {
                    scope.launch {
                        val text = withContext(Dispatchers.IO) {
                            runCatching { resolver.openInputStream(file.uri)?.bufferedReader()?.use { it.readText() } }.getOrNull()
                        }
                        // Use a CSV reader that handles quoted fields; split keeps the recipe short.
                        val rows = text.orEmpty().lines().filter { it.isNotBlank() }.map { line -> line.split(',').map { it.trim() } }
                        if (rows.size < 2) {
                            readError = "This file has no data rows under the header row."
                        } else {
                            readError = null
                            fileName = file.name
                            table = rows
                            val found = rows.first().map { MonarchColumnMappingSource(it) }
                            mapping = MonarchColumnMappingDefaults.mapping(MonarchColumnMappingDefaults.suggest(found, fields))
                            step = 1
                        }
                    }
                }
            },
            accept = listOf("text/csv", "text/comma-separated-values"),
            maxFiles = 1,
            maxSize = {{maxSize}},
            errorText = readError,
            labels = MonarchFileUploadLabels(label = "Drag and drop a CSV file here", browse = "Choose file"),
            )
            MonarchLink(text = {{template}}, onClick = { /* Download the template. */ }, variant = MonarchLinkVariant.Standalone)
        }
        1 -> {
            MonarchColumnMapping(
                sources = sources,
                mapping = mapping,
                fields = fields,
                onMappingChange = { mapping = it },
                modifier = Modifier.fillMaxWidth().weight(1f),
                showIssues = showIssues,
            )
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchButton(text = "Back", onClick = { step = 0 })
                MonarchButton(
                    text = "Check rows",
                    onClick = {
                        showIssues = true
                        if (MonarchColumnMappingDefaults.issues(mapping, fields).isEmpty) step = 2
                    },
                    variant = MonarchButtonVariant.Primary,
                )
            }
        }
        2 -> {
            MonarchPreviewRows(
                rows = previewRows,
                columns = fields.map { MonarchPreviewRowsColumn(it.id, it.label) },
                label = "Preview of $fileName",
                filter = filter,
                onFilterChange = { filter = it },
                modifier = Modifier.fillMaxWidth().weight(1f),
            )
            if (importing) MonarchProgress(modifier = Modifier.fillMaxWidth(), label = "Importing ${ready.size} rows")
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchButton(text = "Back", onClick = { step = 1 }, enabled = !importing)
                MonarchButton(
                    text = if (ready.size == 1) "Import 1 row" else "Import ${ready.size} rows",
                    onClick = { importing = true },
                    variant = MonarchButtonVariant.Primary,
                    enabled = ready.isNotEmpty() && !importing,
                )
            }
        }
        else -> {
            MonarchBanner(
                message = "$imported created, ${previewRows.size - imported} skipped.",
                tone = MonarchTone.Success,
                title = "Import finished",
                announcement = MonarchBannerAnnouncement.Polite,
            )
            MonarchButton(
                text = "Import another file",
                onClick = {
                    table = emptyList()
                    mapping = emptyMap()
                    showIssues = false
                    step = 0
                },
            )
        }
    }
}

examples.setupTemplate:
val fields = listOf(
    MonarchColumnMappingField(id = "name", label = "Name", required = true, aliases = listOf("Full name")),
    MonarchColumnMappingField(id = "email", label = "Email", required = true, aliases = listOf("E-mail", "Mail")),
    MonarchColumnMappingField(id = "company", label = "Company"),
)
val steps = listOf(
    MonarchStepperStep(id = "upload", label = {{steps.0}}),
    MonarchStepperStep(id = "map", label = {{steps.1}}),
    MonarchStepperStep(id = "preview", label = {{steps.2}}),
    MonarchStepperStep(id = "results", label = {{steps.3}}),
)
val resolver = LocalContext.current.contentResolver
val scope = rememberCoroutineScope()
var step by remember { mutableIntStateOf(0) }
var fileName by remember { mutableStateOf("") }
// The header row first, then the data rows.
var table by remember { mutableStateOf(listOf<List<String>>()) }
var mapping by remember { mutableStateOf(mapOf<String, String>()) }
var showIssues by remember { mutableStateOf(false) }
var filter by remember { mutableStateOf<MonarchPreviewRowStatus?>(null) }
var importing by remember { mutableStateOf(false) }
var imported by remember { mutableIntStateOf(0) }
var readError by remember { mutableStateOf<String?>(null) }
val headers = table.firstOrNull().orEmpty()
val sources = headers.mapIndexed { column, header ->
    MonarchColumnMappingSource(header, table.drop(1).take(3).map { it.getOrElse(column) { "" } })
}
val previewRows = table.drop(1).mapIndexed { index, cells ->
    val values = mapping.entries.associate { (column, field) -> field to cells.getOrNull(headers.indexOf(column)) }
    val missing = fields.filter { it.required && values[it.id].isNullOrBlank() }
    // The app adds its own checks here, such as duplicates found on the server.
    MonarchPreviewRow(index + 1, values, errors = missing.map { MonarchPreviewRowIssue("${it.label} is required", it.label) })
}
val ready = previewRows.filter { it.outcome != MonarchPreviewRowStatus.Error }
LaunchedEffect(importing) {
    if (importing) {
        // Save the ready rows on the server here.
        imported = ready.size
        importing = false
        step = 3
    }
}

